import { boolean, datetime, decimal, int, json, mysqlEnum, mysqlTable, text, varchar } from 'drizzle-orm/mysql-core';
import { idColumn, fkColumn } from './columns';

/**
 * A lead is any inbound contact/interest signal — currently generated by
 * the Astro site's public/api/contact.php form, and by this admin app's
 * own public-facing intake once/if it gets one. This table is the
 * canonical record either way; the PHP handler writes here over HTTP
 * (via a narrow, authenticated internal API route) rather than directly
 * to this database, since the static site has no server-side DB access
 * of its own.
 */
export const leads = mysqlTable('leads', {
  id: idColumn(),
  fullName: text('full_name').notNull(),
  email: varchar('email', { length: 255 }),
  phone: varchar('phone', { length: 50 }),
  company: text('company'),
  message: text('message'),
  source: varchar('source', { length: 100 }),
  status: mysqlEnum('status', ['new', 'contacted', 'qualified', 'converted', 'lost']).notNull().default('new'),
  assignedToUserId: fkColumn('assigned_to_user_id'),
  createdAt: datetime('created_at').notNull().$defaultFn(() => new Date()),
  updatedAt: datetime('updated_at').notNull().$defaultFn(() => new Date()),
});

/**
 * Booking requests — originally just the Astro site's free 30-minute
 * booking system (public/api/book.php), mirrored here for admin
 * visibility/workflow (same cross-boundary reasoning as `leads` above).
 * Now also the record for the owner's PAID consultation model (see
 * docs/PRICING.md): the columns below `notes` are nullable because the
 * legacy book.php path still only ever sends the original fields — a
 * row from that path simply has every paid-consultation field left
 * null, never a fabricated 0/"free" value standing in for "paid but
 * unknown".
 */
export const consultations = mysqlTable('consultations', {
  id: idColumn(),
  leadId: fkColumn('lead_id'),
  fullName: text('full_name').notNull(),
  email: varchar('email', { length: 255 }),
  phone: varchar('phone', { length: 50 }),
  // Free text, not an ISO code — book.php collects "Please enter your
  // country" as an open text field, not a country-code picker; the new
  // paid-consultation form does too (for the same reason: a visitor
  // typing their own country is simpler and more reliable than a long
  // <select>, and detectedCountryCode below already carries the
  // IP/locale-derived ISO code for anything that needs one).
  country: varchar('country', { length: 100 }),
  requestedAt: datetime('requested_at').notNull(),
  status: mysqlEnum('status', ['requested', 'confirmed', 'completed', 'cancelled', 'no_show']).notNull().default('requested'),
  notes: text('notes'),
  createdAt: datetime('created_at').notNull().$defaultFn(() => new Date()),

  // --- Paid-consultation fields (docs/PRICING.md §8) — all nullable ---
  companyName: text('company_name'),
  industry: text('industry'),
  website: text('website'),
  companySize: mysqlEnum('company_size', ['startup', 'small', 'medium', 'large', 'enterprise']),
  numberOfEmployees: varchar('number_of_employees', { length: 50 }),
  securityConcern: text('security_concern'),
  preferredPackageSlug: varchar('preferred_package_slug', { length: 100 }),
  timezone: varchar('timezone', { length: 100 }),
  additionalInformation: text('additional_information'),

  // Pricing/currency snapshot at the moment the visitor booked — never
  // recomputed later, so a change to consultation_settings.fee_usd or
  // fx_rates never silently rewrites what a past visitor actually saw
  // and agreed to pay (docs/PRICING.md §9's "do not silently change the
  // currency at checkout" requirement, applied to the record, not just
  // the UI).
  feeUsd: decimal('fee_usd', { precision: 10, scale: 2 }),
  displayedCurrency: varchar('displayed_currency', { length: 3 }),
  displayedAmount: decimal('displayed_amount', { precision: 12, scale: 2 }),
  fxRateTimestamp: datetime('fx_rate_timestamp'),
  // How displayedCurrency was arrived at — 'ip' | 'locale' | 'manual' |
  // 'fallback_usd' — see src/lib/pricing/currency.ts. Never geolocation
  // more precise than country-level (the brief explicitly rules out
  // requesting GPS location).
  countryDetectionSource: varchar('country_detection_source', { length: 20 }),

  // The actual USD charge always authoritatively lives on the linked
  // invoice/payment rows (apps/admin already has both — see crm.ts
  // above), never duplicated or re-derived here; these are just the
  // links. paymentStatus mirrors payments.status at booking time for
  // fast list-page rendering without a join — always re-read the real
  // payment row before treating a consultation as actually paid.
  invoiceId: fkColumn('invoice_id'),
  paymentId: fkColumn('payment_id'),
  paymentStatus: mysqlEnum('payment_status', ['pending', 'pending_verification', 'succeeded', 'failed', 'refunded']),
});

export const customers = mysqlTable('customers', {
  id: idColumn(),
  fullName: text('full_name').notNull(),
  email: varchar('email', { length: 255 }),
  phone: varchar('phone', { length: 50 }),
  company: text('company'),
  convertedFromLeadId: fkColumn('converted_from_lead_id'),
  createdAt: datetime('created_at').notNull().$defaultFn(() => new Date()),
});

/**
 * Review requests sent to real customers after a real engagement — the
 * link generated always points at the business's actual Google Business
 * Profile review URL. This table tracks who was asked and when; it never
 * stores or fabricates the review content itself, which lives on Google,
 * not here.
 */
export const reviewRequests = mysqlTable('review_requests', {
  id: idColumn(),
  customerId: fkColumn('customer_id').notNull(),
  requestedByUserId: fkColumn('requested_by_user_id'),
  sentAt: datetime('sent_at').notNull().$defaultFn(() => new Date()),
  status: mysqlEnum('status', ['sent', 'completed', 'declined']).notNull().default('sent'),
});

/**
 * Genuine testimonials only — collected from real clients. `verified`
 * distinguishes a testimonial the business has independently confirmed
 * (e.g. a linked, checkable Google review) from one submitted directly
 * but not yet cross-checked; both must be real, never invented.
 */
export const testimonials = mysqlTable('testimonials', {
  id: idColumn(),
  customerId: fkColumn('customer_id'),
  authorName: text('author_name').notNull(),
  quote: text('quote').notNull(),
  sourceUrl: text('source_url'),
  verificationStatus: mysqlEnum('verification_status', ['pending', 'verified', 'unverified']).notNull().default('pending'),
  status: mysqlEnum('status', ['draft', 'published']).notNull().default('draft'),
  createdByUserId: fkColumn('created_by_user_id'),
  createdAt: datetime('created_at').notNull().$defaultFn(() => new Date()),
});

export const paymentMethods = mysqlTable('payment_methods', {
  id: idColumn(),
  // Never raw card data — a payment provider's own tokenized
  // reference/method id only (e.g. a Stripe PaymentMethod id).
  provider: varchar('provider', { length: 50 }).notNull(),
  providerMethodRef: text('provider_method_ref').notNull(),
  customerId: fkColumn('customer_id').notNull(),
  label: text('label'),
  createdAt: datetime('created_at').notNull().$defaultFn(() => new Date()),
});

export const invoices = mysqlTable('invoices', {
  id: idColumn(),
  customerId: fkColumn('customer_id').notNull(),
  invoiceNumber: varchar('invoice_number', { length: 50 }).notNull().unique(),
  currency: varchar('currency', { length: 3 }).notNull().default('USD'),
  amountDue: decimal('amount_due', { precision: 10, scale: 2 }).notNull(),
  status: mysqlEnum('status', ['draft', 'sent', 'paid', 'void', 'overdue']).notNull().default('draft'),
  dueDate: datetime('due_date'),
  createdByUserId: fkColumn('created_by_user_id'),
  createdAt: datetime('created_at').notNull().$defaultFn(() => new Date()),
});

/**
 * Provider-abstracted: `provider` names which real gateway processed it
 * (or 'manual' for a bank transfer recorded by hand), and no payment
 * provider is wired to live credentials in code until the user supplies
 * real ones — see docs/PAYMENTS.md once written.
 */
export const payments = mysqlTable('payments', {
  id: idColumn(),
  invoiceId: fkColumn('invoice_id'),
  customerId: fkColumn('customer_id').notNull(),
  provider: varchar('provider', { length: 50 }).notNull(),
  providerPaymentRef: text('provider_payment_ref'),
  amount: decimal('amount', { precision: 10, scale: 2 }).notNull(),
  currency: varchar('currency', { length: 3 }).notNull().default('USD'),
  status: mysqlEnum('status', ['pending', 'succeeded', 'failed', 'refunded']).notNull().default('pending'),
  metadata: json('metadata').$type<Record<string, unknown>>(),
  recordedByUserId: fkColumn('recorded_by_user_id'),
  createdAt: datetime('created_at').notNull().$defaultFn(() => new Date()),
});

/**
 * Admin-configurable manual payment options (bank transfer, crypto
 * wallet, etc.) shown to staff when recording a payment by hand — same
 * shape and purpose as apps/learn's payment_methods table (a deliberate
 * naming distinction: this app's existing `paymentMethods` table above
 * is unrelated scaffolding for a tokenized gateway reference, not this
 * concept). Not surfaced to the public; shahidiqbal.com has no
 * self-serve checkout of its own.
 */
export const manualPaymentMethods = mysqlTable('manual_payment_methods', {
  id: idColumn(),
  name: text('name').notNull(),
  type: mysqlEnum('type', ['bank_transfer', 'crypto', 'mobile_wallet', 'other']).notNull(),
  instructions: text('instructions'),
  walletAddress: text('wallet_address'),
  isActive: boolean('is_active').notNull().default(true),
  sortOrder: int('sort_order').notNull().default(0),
  createdAt: datetime('created_at').notNull().$defaultFn(() => new Date()),
});

export type Lead = typeof leads.$inferSelect;
export type Consultation = typeof consultations.$inferSelect;
export type Testimonial = typeof testimonials.$inferSelect;
export type ManualPaymentMethod = typeof manualPaymentMethods.$inferSelect;
